import java.io.File;

public class Foo {
    void m(File f) {
        f.delete();
    }
}

import java.io.File;
import java.io.FileInputStream;
import java.io.Reader;
import java.sql.ResultSet;
import java.util.ArrayDeque;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class Foo {
    void m(File f, File g, FileInputStream in, Reader r, ArrayDeque<String> q, BlockingQueue<String> bq,
            ReentrantLock lock, Semaphore s, CountDownLatch latch, ResultSet rs) throws Exception {
        f.mkdirs();
        f.renameTo(g);
        in.read(new byte[8]);
        r.skip(10L);
        q.offer("a");
        bq.offer("b", 1, TimeUnit.SECONDS);
        lock.tryLock();
        s.tryAcquire(2);
        rs.next();
    }
}

import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.util.List;
import java.util.Queue;

public class Foo {
    boolean m(File f, InputStream in, List<String> list, Queue<String> q) throws IOException {
        if (!f.delete()) {
            throw new IOException("cannot delete " + f);
        }
        boolean created = f.mkdirs();
        in.read();
        list.add("a");
        q.add("b");
        return created && f.setReadable(true);
    }
}
